	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return fmt.Errorf("output %q is unsafe: destination directory was replaced", absOut)
	}
	if id, ok := fileIDOf(info); !ok || id.dev != uint64(pinStat.Dev) || id.ino != uint64(pinStat.Ino) {
