			if err != nil {
				t.Fatal(err)
			}
			_, err = store.ExportSnapshot("fresh", "", out)
			if err == nil || !strings.Contains(err.Error(), "hard link to repository file") {
				t.Fatalf("expected hardlink error, got %v", err)
			}
			after, err := os.ReadFile(repoFile)
			if err != nil {
