func TestExportFailureLeavesOutputStateUntouched(t *testing.T) {
	root, store, entry := exportVault(t, "alpha")
	t.Run("missing snapshot names the snapshot", func(t *testing.T) {
		out := filepath.Join(t.TempDir(), "snap.pkg")
